cd /app && python3 << 'EOF'
# Let me search all the text files more comprehensively
import os

for filename in os.listdir('/app/resources/'):
    if filename.endswith('.txt'):
        try:
            with open(f'/app/resources/{filename}', 'r', errors='ignore') as f:
                content = f.read()
                # Search for any pattern that looks like an estimate for year 2025
                if '2025' in content:
                    print(f"\n=== {filename} ===")
                    # Show context around 2025
                    lines = content.split('\n')
                    for i, line in enumerate(lines):
                        if '2025' in line:
                            print(f"Line {i}: {line[:150]}")
        except Exception as e:
            print(f"Error with {filename}: {e}")
EOF
